gold  = [("지난달 스타벅스 결제 유저 수는?", "1204"), ("A카페의 업종은?", "카페"), ("B식당 재방문 비율은?", "0.00")]
agent = ["1204", "음식점", "0"]
def same(a, b):
    try:
        return float(a) == float(b)
    except ValueError:
        return a.strip() == b.strip()
score = [same(a, g) for (_, g), a in zip(gold, agent)]
print(score, f"정답률 {sum(score)}/{len(score)}")
# [True, False, True] 정답률 2/3

import math
baskets = {"u1": ["스타벅스", "투썸", "쿠팡"], "u2": ["스타벅스", "투썸"], "u3": ["GS25", "CU"],
           "u4": ["GS25", "CU", "쿠팡"], "u5": ["스타벅스", "쿠팡"]}
users = sorted(baskets)
brands = sorted({b for v in baskets.values() for b in v})
vec = {b: [1 if b in baskets[u] else 0 for u in users] for b in brands}
def cos(a, b):
    return sum(x * y for x, y in zip(a, b)) / (math.sqrt(sum(a)) * math.sqrt(sum(b)))
for b in ["스타벅스", "GS25"]:
    print(b, sorted(((round(cos(vec[b], vec[o]), 2), o) for o in brands if o != b), reverse=True)[:3])
# 스타벅스 [(0.82, '투썸'), (0.67, '쿠팡'), (0.0, 'GS25')]
# GS25 [(1.0, 'CU'), (0.41, '쿠팡'), (0.0, '투썸')]
